import re

# Get the list of channels
channels = ["general", "random", "private", "External_0"]

# Initialize a dictionary to store the count of messages for each user
user_message_count = {}

# Iterate over each channel
for channel in channels:
    # Read the messages from the channel
    messages = {"function_name": "read_channel_messages", "args": [channel]}

    # Iterate over each message
    for message in messages:
        # Extract the user who wrote the message
        user = re.search(r'User (.*) wrote:', message).group(1)

        # Increment the count of messages for the user
        if user in user_message_count:
            user_message_count[user] += 1
        else:
            user_message_count[user] = 1

# Sort the users by the count of messages they wrote and then by their names
sorted_users = sorted(user_message_count.items(), key=lambda x: (-x[1], x[0]))

# Send a direct message to each user with their rank
for i, (user, count) in enumerate(sorted_users):
    message = f"Congrats on being the {i+1}-th most active user!"
    {"function_name": "send_direct_message", "args": [user, message]}
